FROM comp;

CREATE VIEW "public"."vc_ecommerce" AS
WITH comp AS (
  SELECT base.*,
    (SELECT COALESCE(array_agg(((btbl."product_id")::text) ORDER BY btbl."nocopk"), ARRAY[]::text[]) FROM "public"."_m2m_ecommerce_products_products" j JOIN "public"."vc_products" btbl ON btbl."nocopk" = j."products_id" WHERE j."ecommerce_id" = base."nocopk") AS "available_from_products",
    (SELECT COALESCE(array_agg(((btbl."lot_id")::text) ORDER BY btbl."nocopk"), ARRAY[]::text[]) FROM "public"."_m2m_ecommerce_lots_lots" j JOIN "public"."vc_lots" btbl ON btbl."nocopk" = j."lots_id" WHERE j."ecommerce_id" = base."nocopk") AS "available_from_lots"
  FROM "public"."v_ecommerce" base
)
SELECT comp.*
FROM comp;

CREATE VIEW "public"."vc_ecommerce_orders" AS
WITH comp AS (
  SELECT base.*,
    (SELECT COALESCE(array_agg(((btbl."name_mat")::text) ORDER BY btbl."nocopk"), ARRAY[]::text[]) FROM "public"."_m2m_ecommerce_orders_products_products" j JOIN "public"."products" btbl ON btbl."nocopk" = j."products_id" WHERE j."ecommerce_orders_id" = base."nocopk") AS "products_report",
    (SELECT COALESCE(array_agg(((btbl."product_id")::text) ORDER BY btbl."nocopk"), ARRAY[]::text[]) FROM "public"."_m2m_ecommerce_orders_products_products" j JOIN "public"."vc_products" btbl ON btbl."nocopk" = j."products_id" WHERE j."ecommerce_orders_id" = base."nocopk") AS "product_ids_report"
  FROM "public"."v_ecommerce_orders" base
)
SELECT comp.*
FROM comp;

COMMIT;
